        ORD     <UnexpectedIrqFlags,Z
        STD     <UnexpectedIrqFlags,Z
        TSX
        LDD     $06,X
        STD     <UnexpectedIrqStack6,Z
        LDD     $04,X
        STD     <UnexpectedIrqStack4,Z
        PULM    K,X,D
        RTI
        dc.b    $27,$4C,$27,$4C

